import React, { useState, useEffect } from 'react';
import { X, ExternalLink, Twitter, TrendingUp, Users, Shield, Copy, Star } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import watchlistService from '../services/watchlistService';

const TokenDetails = ({ token, onClose }) => {
  const { isAuthenticated } = useAuth();
  const [isInWatchlist, setIsInWatchlist] = useState(false);
  const [watchlistLoading, setWatchlistLoading] = useState(false);

  // Check if token is in watchlist when component mounts or user changes
  useEffect(() => {
    const checkWatchlistStatus = async () => {
      if (isAuthenticated && token?.symbol) {
        try {
          const inWatchlist = await watchlistService.isInWatchlist(token.symbol);
          setIsInWatchlist(inWatchlist);
        } catch (error) {
          console.error('Error checking watchlist status:', error);
        }
      }
    };

    checkWatchlistStatus();
  }, [isAuthenticated, token?.symbol]);

  if (!token) return null;

  // Debug: Log the token data to see what we're receiving
  console.log('TokenDetails received token:', token);

  // Toggle watchlist
  const toggleWatchlist = async () => {
    if (!isAuthenticated) {
      alert('Please login to add tokens to your watchlist!');
      return;
    }

    setWatchlistLoading(true);
    try {
      if (isInWatchlist) {
        await watchlistService.removeFromWatchlist(token.symbol);
        setIsInWatchlist(false);
        console.log(`✅ Removed ${token.symbol} from watchlist`);
      } else {
        // Prepare token data for watchlist
        const tokenData = {
          symbol: token.symbol,
          name: token.name,
          image: token.image,
          contractAddress: token.contractAddress,
          score: token.score || token.overallScore || 0,
          marketCap: token.marketCap,
          price: token.price,
          priceChange24h: token.priceChange24h
        };

        await watchlistService.addToWatchlist(tokenData);
        setIsInWatchlist(true);
        console.log(`✅ Added ${token.symbol} to watchlist`);
      }
    } catch (error) {
      console.error('Error updating watchlist:', error);
      alert(`Failed to ${isInWatchlist ? 'remove from' : 'add to'} watchlist. Please try again.`);
    }
    setWatchlistLoading(false);
  };

  const getScoreColor = (score) => {
    if (score >= 8) return 'text-green-400';
    if (score >= 6) return 'text-yellow-400';
    if (score >= 4) return 'text-orange-400';
    return 'text-red-400';
  };

  const getScoreLabel = (score) => {
    if (score >= 8) return 'Excellent';
    if (score >= 6) return 'Good';
    if (score >= 4) return 'Fair';
    return 'Poor';
  };

  // Helper function to safely format numbers
  const safeToFixed = (value, decimals = 2) => {
    if (!value || isNaN(value)) return '0';
    const num = Number(value);
    return isNaN(num) ? '0' : num.toFixed(decimals);
  };

  // Helper function to safely format market cap
  const formatMarketCap = (marketCap) => {
    if (!marketCap || isNaN(marketCap)) return 'N/A';
    const num = Number(marketCap);
    if (isNaN(num)) return 'N/A';

    if (num >= 1e9) return `$${(num / 1e9).toFixed(1)}B`;
    if (num >= 1e6) return `$${(num / 1e6).toFixed(1)}M`;
    if (num >= 1e3) return `$${(num / 1e3).toFixed(1)}K`;
    return `$${num.toFixed(0)}`;
  };

  // Helper function to format Jupiter API data
  const formatJupiterData = (data) => {
    if (!data) return null;

    const formatNumber = (num) => {
      if (!num || isNaN(num)) return 'N/A';
      if (num >= 1e9) return `$${(num / 1e9).toFixed(2)}B`;
      if (num >= 1e6) return `$${(num / 1e6).toFixed(2)}M`;
      if (num >= 1e3) return `$${(num / 1e3).toFixed(2)}K`;
      return `$${num.toFixed(2)}`;
    };

    const formatPercentage = (num) => {
      if (!num || isNaN(num)) return 'N/A';
      return `${num > 0 ? '+' : ''}${num.toFixed(2)}%`;
    };

    return {
      formatNumber,
      formatPercentage
    };
  };

  // Get Jupiter data formatters
  const jupiterFormatters = formatJupiterData(token.jupiterData);

  // Helper function to safely format price
  const formatPrice = (price) => {
    if (!price || isNaN(price)) return 'N/A';
    const num = Number(price);
    if (isNaN(num)) return 'N/A';

    if (num >= 1) return `$${num.toFixed(4)}`;
    if (num >= 0.01) return `$${num.toFixed(6)}`;
    return `$${num.toExponential(2)}`;
  };

  // Helper function to safely format volume
  const formatVolume = (volume) => {
    if (!volume || isNaN(volume)) return 'N/A';
    const num = Number(volume);
    if (isNaN(num)) return 'N/A';

    if (num >= 1e9) return `$${(num / 1e9).toFixed(1)}B`;
    if (num >= 1e6) return `$${(num / 1e6).toFixed(1)}M`;
    if (num >= 1e3) return `$${(num / 1e3).toFixed(1)}K`;
    return `$${num.toFixed(0)}`;
  };

  const copyToClipboard = (text) => {
    navigator.clipboard.writeText(text).then(() => {
      // You could add a toast notification here
      console.log('Copied to clipboard:', text);
    }).catch(err => {
      console.error('Failed to copy:', err);
    });
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-dark-card border border-solana-purple rounded-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto">
        <div className="p-6">
          {/* Header */}
          <div className="flex justify-between items-start mb-6">
            <div className="flex items-center space-x-4">
              {token.image && (
                <img 
                  src={token.image} 
                  alt={`${token.symbol} logo`}
                  className="w-16 h-16 rounded-full border-2 border-solana-purple"
                  onError={(e) => {
                    e.target.src = `https://via.placeholder.com/64x64/9945FF/FFFFFF?text=${token.symbol.charAt(0)}`;
                  }}
                />
              )}
              <div>
                <h2 className="text-2xl font-bold text-solana-purple">${token.symbol}</h2>
                <p className="text-gray-400">{token.name}</p>
                {/* Debug: Log token data */}
                {console.log('TokenDetails Debug:', {
                  symbol: token.symbol,
                  contractAddress: token.contractAddress,
                  hasRealContract: token.hasRealContract,
                  type: typeof token.contractAddress,
                  length: token.contractAddress?.length
                })}
                {token.contractAddress ? (
                  <div className="flex items-center space-x-2 mt-2">
                    <span className="text-xs text-gray-500">CA:</span>
                    <code className="text-xs bg-dark-bg px-2 py-1 rounded border border-gray-700 text-gray-300">
                      {token.contractAddress.length > 20 
                        ? `${token.contractAddress.slice(0, 6)}...${token.contractAddress.slice(-6)}`
                        : token.contractAddress
                      }
                    </code>
                    <button
                      onClick={() => copyToClipboard(token.contractAddress)}
                      className="text-gray-400 hover:text-white transition-colors"
                      title="Copy contract address"
                    >
                      <Copy size={14} />
                    </button>
                  </div>
                ) : (
                  <div className="flex items-center space-x-2 mt-2">
                    <span className="text-xs text-red-500">CA: Not available</span>
                  </div>
                )}
              </div>
            </div>
            <div className="flex items-center space-x-2">
              {/* Favorite Button */}
              <button
                onClick={toggleWatchlist}
                disabled={watchlistLoading}
                className={`p-2 rounded-lg transition-all duration-200 ${
                  isInWatchlist 
                    ? 'text-yellow-400 bg-yellow-400/10 hover:bg-yellow-400/20' 
                    : 'text-gray-400 hover:text-yellow-400 hover:bg-yellow-400/10'
                } ${watchlistLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
                title={isInWatchlist ? 'Remove from watchlist' : 'Add to watchlist'}
              >
                {watchlistLoading ? (
                  <div className="w-5 h-5 border-2 border-gray-400 border-t-transparent rounded-full animate-spin"></div>
                ) : (
                  <Star 
                    size={20} 
                    fill={isInWatchlist ? 'currentColor' : 'none'} 
                  />
                )}
              </button>

              {/* Close Button */}
              <button
                onClick={onClose}
                className="text-gray-400 hover:text-white transition-colors p-2"
              >
                <X size={24} />
              </button>
            </div>
          </div>

          {/* Market Data */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
            <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
              <div className="flex items-center justify-between">
                <span className="text-gray-400">Market Cap</span>
                <span className="text-green-400">💰</span>
              </div>
              <div className="text-2xl font-bold text-white">
                {formatMarketCap(token.marketCap)}
              </div>
              <div className="text-sm text-gray-400">
                {token.marketCapRank ? `Rank #${token.marketCapRank}` : 'Unranked'}
              </div>
            </div>

            <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
              <div className="flex items-center justify-between">
                <span className="text-gray-400">Price</span>
                <span className="text-yellow-400">💵</span>
              </div>
              <div className="text-2xl font-bold text-white">
                {formatPrice(token.currentPrice)}
              </div>
              <div className="space-y-1">
                <div className={`text-sm ${
                  token.priceChange1h > 0 ? 'text-green-400' : 
                  token.priceChange1h < 0 ? 'text-red-400' : 'text-gray-400'
                }`}>
                  {token.priceChange1h > 0 ? '+' : ''}{safeToFixed(token.priceChange1h, 2)}% (1h)
                </div>
                <div className={`text-sm ${
                  token.priceChange24h > 0 ? 'text-green-400' : 
                  token.priceChange24h < 0 ? 'text-red-400' : 'text-gray-400'
                }`}>
                  {token.priceChange24h > 0 ? '+' : ''}{safeToFixed(token.priceChange24h, 2)}% (24h)
                </div>
              </div>
            </div>

            <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
              <div className="flex items-center justify-between">
                <span className="text-gray-400">Volume (24h)</span>
                <span className="text-blue-400">📊</span>
              </div>
              <div className="text-2xl font-bold text-white">
                {formatVolume(token.volume24h)}
              </div>
              <div className="text-sm text-gray-400">
                24h Trading Volume
              </div>
            </div>

            <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
              <div className="flex items-center justify-between">
                <span className="text-gray-400">7d Change</span>
                <span className="text-purple-400">📈</span>
              </div>
              <div className={`text-2xl font-bold ${
                token.priceChange7d > 0 ? 'text-green-400' : 
                token.priceChange7d < 0 ? 'text-red-400' : 'text-gray-400'
              }`}>
                {token.priceChange7d > 0 ? '+' : ''}{safeToFixed(token.priceChange7d, 2)}%
              </div>
              <div className="text-sm text-gray-400">
                7 Day Performance
              </div>
            </div>
          </div>

          {/* Score Overview */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
            <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
              <div className="flex items-center justify-between">
                <span className="text-gray-400">Overall Score</span>
                <TrendingUp className="text-solana-purple" size={20} />
              </div>
                      <div className={`text-2xl font-bold ${getScoreColor(token.score || token.overallScore || 0)}`}>
          {safeToFixed(token.score || token.overallScore || 0, 1)}/10
        </div>
        <div className={`text-sm ${getScoreColor(token.score || token.overallScore || 0)}`}>
          {getScoreLabel(token.score || token.overallScore || 0)}
        </div>
            </div>

            <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
              <div className="flex items-center justify-between">
                <span className="text-gray-400">Mentions (24h)</span>
                <Twitter className="text-blue-400" size={20} />
              </div>
              <div className="text-2xl font-bold text-white">
                {(token.mentions || 0).toLocaleString()}
              </div>
              <div className="text-sm text-gray-400">
                {token.mentionsTrend > 0 ? '+' : ''}{(token.mentionsTrend || 0).toFixed(1)}% vs yesterday
              </div>
            </div>

            <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
              <div className="flex items-center justify-between">
                <span className="text-gray-400">Community</span>
                <Users className="text-solana-green" size={20} />
              </div>
              <div className={`text-2xl font-bold ${getScoreColor(token.communityScore)}`}>
                {token.communityScore ? token.communityScore.toFixed(1) : 'N/A'}/10
              </div>
              <div className="text-sm text-gray-400">
                Quality Score
              </div>
            </div>
          </div>

          {/* Profile Information */}
          <div className="mb-6">
            <h3 className="text-lg font-semibold mb-3 text-white">Profile Information</h3>
            <div className="space-y-3">
              <div className="flex items-center justify-between p-3 bg-dark-bg rounded-lg border border-gray-700">
                <div className="flex items-center space-x-3">
                  <Shield className={token.hasOfficialProfile ? 'text-green-400' : 'text-red-400'} size={20} />
                  <span className="text-white">Official Profile</span>
                </div>
                <span className={token.hasOfficialProfile ? 'text-green-400' : 'text-red-400'}>
                  {token.hasOfficialProfile ? 'Verified' : 'Not Found'}
                </span>
              </div>

              {token.twitterHandle && (
                <div className="flex items-center justify-between p-3 bg-dark-bg rounded-lg border border-gray-700">
                  <div className="flex items-center space-x-3">
                    <Twitter className="text-blue-400" size={20} />
                    <span className="text-white">Twitter Handle</span>
                  </div>
                  <a
                    href={`https://twitter.com/${token.twitterHandle}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center space-x-1 text-blue-400 hover:text-blue-300"
                  >
                    <span>@{token.twitterHandle}</span>
                    <ExternalLink size={16} />
                  </a>
                </div>
              )}

              <div className="flex items-center justify-between p-3 bg-dark-bg rounded-lg border border-gray-700">
                <div className="flex items-center space-x-3">
                  <Users className="text-solana-green" size={20} />
                  <span className="text-white">Community Type</span>
                </div>
                <span className="text-white">
                  {token.communityType || 'Unknown'}
                </span>
              </div>
            </div>
          </div>

          {/* Recent Social Activity - Enhanced with Real Twitter Data */}
          <div className="mb-6">
            <h3 className="text-lg font-semibold mb-3 text-white flex items-center">
              <span className="mr-2">📱</span>
              Recent Social Activity
              {token.twitterMetrics && (
                <span className="ml-2 text-sm text-blue-400 bg-blue-400/10 px-2 py-1 rounded">
                  Live Twitter Data
                </span>
              )}
            </h3>

            {/* Twitter Metrics Summary */}
            {token.twitterMetrics && (
              <div className="mb-4 p-4 bg-gradient-to-r from-blue-900/20 to-purple-900/20 border border-blue-500/30 rounded-lg">
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <div className="text-center">
                    <div className="text-2xl font-bold text-blue-400">
                      {token.twitterMetrics.mentions?.toLocaleString() || '0'}
                    </div>
                    <div className="text-xs text-gray-400">Total Mentions</div>
                  </div>
                  <div className="text-center">
                    <div className="text-2xl font-bold text-green-400">
                      {token.twitterMetrics.followers?.toLocaleString() || '0'}
                    </div>
                    <div className="text-xs text-gray-400">Followers</div>
                  </div>
                  <div className="text-center">
                    <div className="text-2xl font-bold text-red-400">
                      {token.twitterMetrics.engagement?.likes?.toLocaleString() || '0'}
                    </div>
                    <div className="text-xs text-gray-400">Total Likes</div>
                  </div>
                  <div className="text-center">
                    <div className="text-2xl font-bold text-purple-400">
                      {token.twitterMetrics.engagement?.retweets?.toLocaleString() || '0'}
                    </div>
                    <div className="text-xs text-gray-400">Retweets</div>
                  </div>
                </div>

                {/* Twitter Profile Link */}
                {token.twitterMetrics.username && (
                  <div className="mt-3 text-center">
                    <a
                      href={`https://twitter.com/${token.twitterMetrics.username}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="inline-flex items-center space-x-2 text-blue-400 hover:text-blue-300 transition-colors"
                    >
                      <span>🐦</span>
                      <span>@{token.twitterMetrics.username}</span>
                      <ExternalLink size={14} />
                    </a>
                  </div>
                )}
              </div>
            )}

            {/* Recent Twitter Mentions */}
            {token.twitterMetrics?.recentMentions && token.twitterMetrics.recentMentions.length > 0 ? (
              <div className="space-y-3 max-h-60 overflow-y-auto">
                <div className="text-sm text-gray-400 mb-2">
                  Recent Twitter Mentions ({token.twitterMetrics.recentMentions.length})
                </div>
                {token.twitterMetrics.recentMentions.map((mention, index) => (
                  <div key={index} className="p-4 bg-dark-bg rounded-lg border border-gray-700 hover:border-blue-500/50 transition-colors">
                    {/* Tweet Content */}
                    <div className="mb-3">
                      <p className="text-sm text-gray-300 leading-relaxed">
                        {mention.text.length > 200 
                          ? `${mention.text.substring(0, 200)}...` 
                          : mention.text
                        }
                      </p>
                    </div>

                    {/* Author and Timestamp */}
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center space-x-3">
                        <div className="flex items-center space-x-2">
                          <span className="text-blue-400 font-medium">@{mention.author}</span>
                          {mention.authorName && mention.authorName !== mention.author && (
                            <span className="text-gray-500 text-xs">({mention.authorName})</span>
                          )}
                        </div>
                        <span className="text-gray-500 text-xs">
                          {new Date(mention.createdAt).toLocaleDateString('en-US', {
                            month: 'short',
                            day: 'numeric',
                            hour: '2-digit',
                            minute: '2-digit'
                          })}
                        </span>
                      </div>

                      {/* Platform Badge */}
                      <span className="text-xs bg-blue-500/20 text-blue-400 px-2 py-1 rounded-full">
                        Twitter
                      </span>
                    </div>

                    {/* Engagement Metrics */}
                    <div className="flex items-center justify-between">
                      <div className="flex items-center space-x-4 text-sm">
                        <div className="flex items-center space-x-1 text-red-400">
                          <span>❤️</span>
                          <span>{mention.likes?.toLocaleString() || '0'}</span>
                        </div>
                        <div className="flex items-center space-x-1 text-green-400">
                          <span>🔄</span>
                          <span>{mention.retweets?.toLocaleString() || '0'}</span>
                        </div>
                        <div className="flex items-center space-x-1 text-blue-400">
                          <span>💬</span>
                          <span>{mention.replies?.toLocaleString() || '0'}</span>
                        </div>
                      </div>

                      {/* View Original Link */}
                      <a
                        href={`https://twitter.com/${mention.author}/status/${mention.id}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center space-x-1 text-blue-400 hover:text-blue-300 transition-colors text-xs"
                        title="View original tweet"
                      >
                        <ExternalLink size={12} />
                        <span>View Tweet</span>
                      </a>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              /* Fallback to existing recentPosts or show no data message */
              token.recentPosts && token.recentPosts.length > 0 ? (
                <div className="space-y-2 max-h-40 overflow-y-auto">
                  {token.recentPosts.map((post, index) => (
                    <div key={index} className="p-3 bg-dark-bg rounded-lg border border-gray-700">
                      <p className="text-sm text-gray-300 mb-2">{post.content}</p>
                      <div className="flex justify-between items-center text-xs">
                        <div className="flex items-center space-x-3 text-gray-500">
                          <span>@{post.author}</span>
                          <span>{post.timestamp}</span>
                          {post.platform && (
                            <span className="text-blue-400 capitalize">• {post.platform}</span>
                          )}
                        </div>
                        <div className="flex items-center space-x-3">
                          <span className="text-red-400">❤️ {post.likes}</span>
                          <span className="text-green-400">💬 {post.retweets}</span>
                          {post.url && (
                            <a
                              href={post.url}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="flex items-center space-x-1 text-blue-400 hover:text-blue-300 transition-colors"
                              title="View original post"
                            >
                              <ExternalLink size={12} />
                              <span>View</span>
                            </a>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="p-6 bg-dark-bg rounded-lg border border-gray-700 text-center">
                  <div className="text-gray-400 mb-2">📭</div>
                  <div className="text-gray-400 text-sm">
                    {token.twitterMetrics ? 'No recent Twitter mentions found' : 'No recent social activity data available'}
                  </div>
                  {token.twitterMetrics && (
                    <div className="text-xs text-gray-500 mt-1">
                      Try searching for different terms or check back later
                    </div>
                  )}
                </div>
              )
            )}
          </div>

          {/* Twitter Analytics */}
          {token.twitterData && (
            <div className="mb-6">
              <h3 className="text-lg font-semibold mb-3 text-white">Twitter Analytics</h3>
              <div className="grid grid-cols-2 gap-4">
                <div className="p-3 bg-dark-bg rounded-lg border border-gray-700">
                  <div className="text-sm text-gray-400">Unique Users</div>
                  <div className="text-xl font-bold text-white">
                    {token.twitterData.uniqueUsers?.toLocaleString() || 'N/A'}
                  </div>
                </div>
                <div className="p-3 bg-dark-bg rounded-lg border border-gray-700">
                  <div className="text-sm text-gray-400">Influencer Mentions</div>
                  <div className="text-xl font-bold text-solana-purple">
                    {token.influencerMentions || 0}
                  </div>
                </div>
                <div className="p-3 bg-dark-bg rounded-lg border border-gray-700">
                  <div className="text-sm text-gray-400">Trending Score</div>
                  <div className="text-xl font-bold text-solana-green">
                    {token.twitterData.trendingScore?.toFixed(1) || 'N/A'}/10
                  </div>
                </div>
                <div className="p-3 bg-dark-bg rounded-lg border border-gray-700">
                  <div className="text-sm text-gray-400">Risk Score</div>
                  <div className={`text-xl font-bold ${
                    token.twitterData.riskIndicators?.riskScore < 2 ? 'text-green-400' :
                    token.twitterData.riskIndicators?.riskScore < 5 ? 'text-yellow-400' : 'text-red-400'
                  }`}>
                    {token.twitterData.riskIndicators?.riskScore?.toFixed(1) || 'N/A'}/10
                  </div>
                </div>
              </div>

              {/* Top Hashtags */}
              {token.topHashtags && token.topHashtags.length > 0 && (
                <div className="mt-4">
                  <div className="text-sm text-gray-400 mb-2">Top Hashtags</div>
                  <div className="flex flex-wrap gap-2">
                    {token.topHashtags.slice(0, 5).map((hashtag, index) => (
                      <span
                        key={index}
                        className="px-2 py-1 bg-solana-purple bg-opacity-20 text-solana-purple rounded text-sm"
                      >
                        {hashtag.hashtag} ({hashtag.count})
                      </span>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Metrics Breakdown */}
          <div>
            <h3 className="text-lg font-semibold mb-3 text-white">Metrics Breakdown</h3>
            <div className="space-y-3">
              <div className="flex justify-between items-center">
                <span className="text-gray-400">Sentiment Score</span>
                <span className={`font-semibold ${getScoreColor(token.sentimentScore || 5)}`}>
                  {(token.sentimentScore || 5).toFixed(1)}/10
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-gray-400">Engagement Rate</span>
                <span className="text-white font-semibold">
                  {((token.engagementRate || 0.05) * 100).toFixed(1)}%
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-gray-400">Unique Mentions</span>
                <span className="text-white font-semibold">
                  {(token.uniqueMentions || Math.floor((token.mentions || 0) * 0.7)).toLocaleString()}
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-gray-400">Risk Level</span>
                <span className={`font-semibold ${
                  token.riskLevel === 'Low' ? 'text-green-400' :
                  token.riskLevel === 'Medium' ? 'text-yellow-400' : 'text-red-400'
                }`}>
                  {token.riskLevel || 'Medium'}
                </span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TokenDetails;
